from rules import amount


def solve(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}

    # Filter first so an out-of-cutoff revision cannot replace an eligible one.
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        identity = ("id", event["id"]) if "id" in event else ("anonymous", position)
        revision = event.get("revision", 0)
        previous = winners.get(identity)
        if previous is None or revision >= previous[0]:
            # Iteration order makes the later input event win revision ties.
            winners[identity] = (revision, position, event)

    balances = dict(data.get("opening", {}))
    for _, _, event in sorted(winners.values(), key=lambda item: item[1]):
        if event.get("void", False):
            continue
        key = f'{event.get("account", "default")}|{event.get("currency", "USD")}'
        balances[key] = balances.get(key, 0) + amount(event, data["rounding"])

    return {"balances": balances}
